(async()=>{
  const s=await import('/src/studio/store.ts');
  const m=await import('/src/studio/architect/model.ts');
  const p=await import('/src/studio/architect/persistence.ts');
  const bridge=await import('/src/studio/assistant/architectBridge.ts');
  const id=s.useStudio.getState().job.id;
  const model=m.emptyProject(id);
  const lid=model.levels[0].id;
  const w1=m.newWall(model,lid,[0,0],[8000,0],[{id:'s1',name:'Brick',thickness:230,kind:'solid',hatch:'brick',densityKgM3:1900,rateM2:120,supplierReference:'SUP-01',rateRevision:'R1',wastePercent:5}]);
  w1.id='w-south';w1.lifecycle={status:'existing',reference:'Survey R01'};model.walls.push(w1);
  const w2=m.newWall(model,lid,[8000,0],[8000,6000],[{id:'s2',name:'Brick',thickness:230,kind:'solid',hatch:'brick',densityKgM3:1900,rateM2:120,supplierReference:'SUP-01',rateRevision:'R1',wastePercent:5}]);
  w2.id='w-east';w2.lifecycle={status:'existing',reference:'Survey R01'};model.walls.push(w2);
  const w3=m.newWall(model,lid,[8000,6000],[0,6000],[{id:'s3',name:'Brick',thickness:230,kind:'solid',hatch:'brick',densityKgM3:1900,rateM2:120,supplierReference:'SUP-01',rateRevision:'R1',wastePercent:5}]);
  w3.id='w-north';w3.lifecycle={status:'existing',reference:'Survey R01'};model.walls.push(w3);
  const w4=m.newWall(model,lid,[0,6000],[0,0],[{id:'s4',name:'Brick',thickness:230,kind:'solid',hatch:'brick',densityKgM3:1900,rateM2:120,supplierReference:'SUP-01',rateRevision:'R1',wastePercent:5}]);
  w4.id='w-west';w4.lifecycle={status:'existing',reference:'Survey R01'};model.walls.push(w4);
  const w5=m.newWall(model,lid,[4000,0],[4000,6000],[{id:'s5',name:'Stud',thickness:90,kind:'solid',hatch:'timber',densityKgM3:500,rateM2:70,supplierReference:'SUP-02',rateRevision:'R1',wastePercent:5}]);
  w5.id='w-demo-part';w5.lifecycle={status:'existing',reference:'Survey R01'};model.walls.push(w5);
  model.openings.push({
    id:'d01',revision:1,wallId:'w-south',tag:'D01',kind:'door',
    offset:2000,width:900,height:2100,sill:0,hinge:'left',swing:'in',
    lifecycle:{status:'existing',reference:'Survey R01'}
  });
  model.openings.push({
    id:'w01',revision:1,wallId:'w-south',tag:'W01',kind:'window',
    offset:6000,width:1500,height:1200,sill:900,hinge:'left',swing:'in',
    lifecycle:{status:'existing',reference:'Survey R01'}
  });
  model.roomTags.push({id:'t-lounge',name:'Lounge',point:[2000,3000],levelId:lid,revision:1});
  model.roomTags.push({id:'t-dining',name:'Dining',point:[6000,3000],levelId:lid,revision:1});
  const prepared=bridge.prepareArchitectEdits(model,{
    expectedJobId:id,
    expectedRevision:model.revision,
    operations:[
      {kind:'set-lifecycle',id:'w-demo-part',lifecycle:{status:'demolished',reference:'Demolition D01'}},
      {kind:'set-lifecycle',id:'d01',lifecycle:{status:'demolished',reference:'Demolition D01'}},
      {kind:'set-opening-disposition',id:'d01',disposition:{kind:'infill',reference:'Full Infill D01'}},
      {kind:'set-lifecycle',id:'w01',lifecycle:{status:'demolished',reference:'Demolition D02'}},
      {kind:'set-opening-disposition',id:'w01',disposition:{kind:'partial-infill',reference:'Reduce W01',remainingVoid:{offset:6000,width:900,height:1200,sill:900}}},
      {kind:'set-lifecycle',id:'w-north',lifecycle:{status:'repaired',reference:'Repair R01'}},
      {kind:'set-wall-repair-basis',id:'w-north',basis:{heightMm:2700,reference:'Repair R01'}}
    ]
  });
  if(!prepared.changed.length)throw new Error('prepareArchitectEdits failed to change elements');
  const saveResult=p.saveArchitect(p.loadArchitect(id,localStorage),prepared.draft,localStorage);
  if(saveResult.error)throw new Error('saveArchitect failed: '+saveResult.error);
  return true;
})()

(async()=>{
  const s=await import('/src/studio/store.ts');
  const p=await import('/src/studio/architect/persistence.ts');
  const m=await import('/src/studio/architect/model.ts');
  const st=await import('/src/studio/architect/alterationStage.ts');
  const iss=await import('/src/studio/architect/alterationIssues.ts');
  const id=s.useStudio.getState().job.id;
  const sess=p.loadArchitect(id,localStorage);
  const current=m.validateProject(sess.value);
  current.designRevision='B';
  current.revision=current.revision+1;
  current.openings.push({
    id:'w02',revision:1,wallId:'w-north',tag:'W02',kind:'window',
    offset:4000,width:1800,height:1200,sill:900,hinge:'left',swing:'in',
    lifecycle:{status:'new',reference:'Brief N01'}
  });
  const validNext=m.validateProject(current);
  const basisB=st.createAlterationBasis(validNext,'Reviewed Stage Coordination Set S02');
  const recB=iss.createAlterationIssueRecord(validNext,basisB,{purpose:'For Construction & Contractor Tender'});
  const issuedProj=iss.appendAlterationIssue(validNext,recB);
  p.saveArchitect(sess,issuedProj,localStorage);
  return true;
})()
